package com.fullstack.exp231.controller;
import com.fullstack.exp231.model.*; import com.fullstack.exp231.security.JwtService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") public class AuthController { private final JwtService jwt; public AuthController(JwtService jwt){this.jwt=jwt;} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody LoginRequest r){String role=null; if("admin".equals(r.username())&&"admin123".equals(r.password()))role="ADMIN"; if("user".equals(r.username())&&"user123".equals(r.password()))role="USER"; if(role==null)return ResponseEntity.status(401).body("Invalid username or password"); return ResponseEntity.ok(new LoginResponse(jwt.generate(r.username(),role),r.username(),role));} }
